        total_commits = int(commits_output) if commits_output.isdigit() else 0

        # Last commit
        last_commit, _ = self._run_git(["log", "-1", "--pretty=format:%s|%an|%ad", "--date=short"])

        return {
            "path": str(self.repo_path),
