            )

        owner, repo = skill_id.split("/", 1)

        # Try cache first
        cache = get_cache()
        content = await cache.get_content(skill_id)
        source = "cache"

        if not content:
            # Fetch from API
            client = get_client()
            content = await client.get_skill_content(owner, repo)
